  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
}

/* --- Header / Navigation --- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  padding: var(--space-lg) var(--space-2xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg);
  transition: background-color 0.3s ease;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: var(--space-xl);
  align-items: center;
}

.nav-links a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color 0.2s ease;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 1px;
  background: var(--text-primary);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  z-index: 110;
  background: none;
  border: none;
  padding: 8px;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text-primary);
  transition: all 0.3s ease;
  transform-origin: center;
}

.hamburger.is-open span:nth-child(1) {
  transform: rotate(45deg) translate(4.5px, 4.5px);
}
.hamburger.is-open span:nth-child(2) {
  opacity: 0;
}
.hamburger.is-open span:nth-child(3) {
  transform: rotate(-45deg) translate(4.5px, -4.5px);
}

/* Mobile Overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 105;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-xl);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-overlay.is-open {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: opacity 0.2s ease;
}

.mobile-overlay a:hover {
  opacity: 0.6;
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-4xl) var(--space-2xl) var(--space-3xl);
}

.hero-headline {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 500;
  line-height: 1.08;
  letter-spacing: -0.03em;
  max-width: 900px;
  margin-bottom: var(--space-2xl);
}

/* --- Media Showcase / Triptych --- */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: var(--space-md);
  padding: 0 var(--space-2xl) var(--space-4xl);
}

.media-block {
  aspect-ratio: 3 / 4;
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.media-block--terracotta { background-color: var(--accent-terracotta); }
.media-block--sage { background-color: var(--accent-sage); }
.media-block--sand { background-color: var(--accent-sand); }

/* --- Client Marquee --- */
.marquee-section {
  padding: var(--space-4xl) 0;
  overflow: hidden;
  border-top: 1px solid oklch(85% 0.008 80);
  border-bottom: 1px solid oklch(85% 0.008 80);
}

.marquee-row {
  display: flex;
  width: max-content;
  will-change: transform;
}

.marquee-row:nth-child(odd) {
  animation: marquee-left 30s linear infinite;
}

.marquee-row:nth-child(even) {
  animation: marquee-right 30s linear infinite;
}

.marquee-row + .marquee-row {
  margin-top: var(--space-md);
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 500;
  letter-spacing: -0.01em;
  white-space: nowrap;
  padding: 0 var(--space-lg);
  color: var(--text-secondary);
}

.marquee-item .separator {
  display: inline-block;
  margin: 0 var(--space-sm);
  color: var(--text-tertiary);
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* --- About Section --- */
.about-section {
  padding: var(--space-5xl) var(--space-2xl);
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: var(--space-xl);
}

.about-text {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  line-height: 1.6;
  max-width: var(--reading-width);
  color: var(--text-primary);
}

.about-text p + p {
  margin-top: var(--space-xl);
}

/* --- Founder Letter --- */
.founder-section {
  padding: var(--space-5xl) var(--space-2xl);
  max-width: var(--reading-width);
  margin: 0 auto;
}

.founder-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: var(--space-3xl);
  padding-top: var(--space-4xl);
}

.founder-letter {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 1.8vw, 1.375rem);
  line-height: 1.75;
  color: var(--text-primary);
}

.founder-letter p + p {
  margin-top: var(--space-xl);
}

.founder-letter .sign-off {
  margin-top: var(--space-3xl);
  font-style: italic;
  font-size: 1.1em;
}

/* --- Philosophy Section --- */
.philosophy-section {
  padding: var(--space-5xl) var(--space-2xl);
}

.philosophy-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 700px;
  margin-bottom: var(--space-3xl);
}

.philosophy-text {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 1.8vw, 1.375rem);
  line-height: 1.7;
  max-width: var(--reading-width);
  color: var(--text-secondary);
}

.philosophy-text p + p {
  margin-top: var(--space-xl);
}

/* --- Divider --- */
.section-divider {
  width: 60px;
  height: 1px;
  background: var(--text-tertiary);
  margin: 0 auto;
}

/* --- Services Section --- */
.services-section {
  padding: var(--space-5xl) var(--space-2xl);
}

.services-intro {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 500;
  line-height: 1.3;
  max-width: 600px;
  margin-bottom: var(--space-4xl);
}

.service-block {
  max-width: var(--reading-width);
  margin-bottom: var(--space-3xl);
}

.service-block:last-child {
  margin-bottom: 0;
}

.service-title {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 600;
  margin-bottom: var(--space-md);
}

.service-description {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* --- Clients Page --- */
.clients-header-section {
  padding: var(--space-5xl) var(--space-2xl) var(--space-2xl);
}

.clients-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.clients-heading span {
  font-weight: 400;
  font-size: 0.5em;
  color: var(--text-secondary);
  display: block;
  margin-top: var(--space-md);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2xl) var(--space-xl);
  padding: var(--space-2xl) var(--space-2xl) var(--space-5xl);
}

.client-card {
  border-top: 1px solid oklch(85% 0.008 80);
  padding-top: var(--space-lg);
}

.client-name {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.client-desc {
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--text-secondary);
}

/* --- Contact Page --- */
.contact-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: var(--space-4xl) var(--space-2xl);
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 14rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
  margin-bottom: var(--space-4xl);
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  align-items: center;
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s ease;
}

.contact-links a:hover {
  color: var(--text-primary);
}

/* --- Page Transition / Utility --- */
.page-content {
  padding-top: 72px;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: var(--space-md) var(--space-lg);
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: var(--space-3xl) var(--space-lg) var(--space-2xl);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: var(--space-md);
    padding: 0 var(--space-lg) var(--space-3xl);
  }

  .media-block {
    aspect-ratio: 16 / 9;
  }

  .about-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .founder-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .philosophy-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .services-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .clients-header-section {
    padding: var(--space-4xl) var(--space-lg) var(--space-lg);
  }

  .clients-grid {
    grid-template-columns: 1fr;
    padding: var(--space-lg) var(--space-lg) var(--space-4xl);
  }

  .marquee-item {
    font-size: 1.25rem;
  }

  .contact-heading {
    font-size: clamp(4rem, 20vw, 8rem);
  }
}

@media (max-width: 480px) {
  .hero-headline {
    font-size: 2rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  .marquee-row {
    animation: none !important;
  }

  html {
    scroll-behavior: auto;
  }

  * {
    transition-duration: 0.01ms !important;
  }
}

/* --- Focus Visible --- */
:focus-visible {
  outline: 2px solid var(--text-primary);
  outline-offset: 2px;
}

