  padding: var(--space-5xl) var(--space-2xl);
}

.services-intro {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 500;
  line-height: 1.3;
  max-width: 600px;
  margin-bottom: var(--space-4xl);
}

.service-block {
  max-width: var(--reading-width);
  margin-bottom: var(--space-3xl);
}

.service-block:last-child {
  margin-bottom: 0;
}

.service-title {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 600;
  margin-bottom: var(--space-md);
}

.service-description {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* --- Clients Page --- */
.clients-header-section {
  padding: var(--space-5xl) var(--space-2xl) var(--space-2xl);
}

.clients-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.clients-heading span {
  font-weight: 400;
  font-size: 0.5em;
  color: var(--text-secondary);
  display: block;
  margin-top: var(--space-md);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2xl) var(--space-xl);
  padding: var(--space-2xl) var(--space-2xl) var(--space-5xl);
}

.client-card {
  border-top: 1px solid oklch(85% 0.008 80);
  padding-top: var(--space-lg);
}

.client-name {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.client-desc {
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--text-secondary);
}

/* --- Contact Page --- */
.contact-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: var(--space-4xl) var(--space-2xl);
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 14rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
  margin-bottom: var(--space-4xl);
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  align-items: center;
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s ease;
}

.contact-links a:hover {
  color: var(--text-primary);
}

/* --- Page Transition / Utility --- */
.page-content {
  padding-top: 72px;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: var(--space-md) var(--space-lg);
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: var(--space-3xl) var(--space-lg) var(--space-2xl);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: var(--space-md);
    padding: 0 var(--space-lg) var(--space-3xl);
  }

  .media-block {
    aspect-ratio: 16 / 9;
  }

  .about-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .founder-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .philosophy-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .services-section {
    padding: var(--space-4xl) var(--space-lg);
  }

  .clients-header-section {
    padding: var(--space-4xl) var(--space-lg) var(--space-lg);
  }

  .clients-grid {
    grid-template-columns: 1fr;
    padding: var(--space-lg) var(--space-lg) var(--space-4xl);
  }

  .marquee-item {
    font-size: 1.25rem;
  }

  .contact-heading {
    font-size: clamp(4rem, 20vw, 8rem);
  }
}

@media (max-width: 480px) {
  .hero-headline {
    font-size: 2rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  .marquee-row {
    animation: none !important;
  }

  html {
    scroll-behavior: auto;
  }

  * {
    transition-duration: 0.01ms !important;
  }
}

/* --- Focus Visible --- */
:focus-visible {
  outline: 2px solid var(--text-primary);
  outline-offset: 2px;
}

